INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('78c0d745-b6d4-4464-91b1-7a012cc274eb', 'e0030000-0000-4000-8000-000000000006', 'nl', 'IMPERIAL 150', 'Een groot huis voor het hele jaar voor bouwheren die ruimte en moderne architectuur verwachten. Een uitgebreide leefruimte met een hoge woonkamer die open is naar de zolder en een open keuken vormt het representatieve hart van het huis, terwijl op zolder drie slaapkamers liggen. Twee badkamers, een technische ruimte, grote ramen en de mogelijkheid van een ruim terras.', '2026-10-09T10:39:16.597Z'::timestamptz, '2026-10-09T11:37:46.313Z'::timestamptz, '[{"id":"e0030000-0000-4000-8000-000000000006-room-0","name":"Woonkamer"},{"id":"e0030000-0000-4000-8000-000000000006-room-1","name":"Keuken"},{"id":"e0030000-0000-4000-8000-000000000006-room-2","name":"Portaal"},{"id":"e0030000-0000-4000-8000-000000000006-room-3","name":"Technische ruimte"},{"id":"e0030000-0000-4000-8000-000000000006-room-4","name":"Kamer"},{"id":"e0030000-0000-4000-8000-000000000006-room-5","name":"Kamer"},{"id":"e0030000-0000-4000-8000-000000000006-room-6","name":"Badkamer"},{"id":"e0030000-0000-4000-8000-000000000006-room-7","name":"Verkeersruimte"},{"id":"e0030000-0000-4000-8000-000000000006-room-8","name":"Slaapkamer"},{"id":"e0030000-0000-4000-8000-000000000006-room-9","name":"Slaapkamer"},{"id":"e0030000-0000-4000-8000-000000000006-room-10","name":"Toilet"},{"id":"e0030000-0000-4000-8000-000000000006-room-11","name":"Verkeersruimte"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SIP-panelen: twee constructieplaten met een kern van PIR-schuim.', 'Zadeldak, 35°', 'Het ontwerp is een uitgangspunt: gevel (kleur en materiaal), ramen, terras, indeling en afwerkingsniveau kunnen worden aangepast.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('dc9c5b5f-fa1c-4e5a-a6fc-a0dcdffbcd05', 'e0030000-0000-4000-8000-000000000006', 'de', 'IMPERIAL 150', 'Ein großes Ganzjahreshaus für Bauherren, die Platz und moderne Architektur erwarten. Ein weitläufiger Wohnbereich mit hohem, zum Dachgeschoss offenem Wohnzimmer und offener Küche ist das repräsentative Zentrum des Hauses, im Dachgeschoss liegen drei Schlafzimmer. Zwei Bäder, ein Technikraum, große Fenster und die Möglichkeit einer großzügigen Terrasse.', '2026-10-09T10:39:16.597Z'::timestamptz, '2026-10-09T11:37:46.313Z'::timestamptz, '[{"id":"e0030000-0000-4000-8000-000000000006-room-0","name":"Wohnzimmer"},{"id":"e0030000-0000-4000-8000-000000000006-room-1","name":"Küche"},{"id":"e0030000-0000-4000-8000-000000000006-room-2","name":"Windfang"},{"id":"e0030000-0000-4000-8000-000000000006-room-3","name":"Technikraum"},{"id":"e0030000-0000-4000-8000-000000000006-room-4","name":"Zimmer"},{"id":"e0030000-0000-4000-8000-000000000006-room-5","name":"Zimmer"},{"id":"e0030000-0000-4000-8000-000000000006-room-6","name":"Badezimmer"},{"id":"e0030000-0000-4000-8000-000000000006-room-7","name":"Verkehrsfläche"},{"id":"e0030000-0000-4000-8000-000000000006-room-8","name":"Schlafzimmer"},{"id":"e0030000-0000-4000-8000-000000000006-room-9","name":"Schlafzimmer"},{"id":"e0030000-0000-4000-8000-000000000006-room-10","name":"WC"},{"id":"e0030000-0000-4000-8000-000000000006-room-11","name":"Verkehrsfläche"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'SIP-Paneele: zwei tragende Platten mit Kern aus PIR-Schaum.', 'Satteldach, 35°', 'Der Entwurf ist ein Ausgangspunkt: Fassade (Farbe und Material), Fenster, Terrasse, Raumaufteilung und Ausbaustandard lassen sich anpassen.', NULL) ON CONFLICT DO NOTHING;
